#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Publish every drevalpy dataset (the assembled MuData files and TOYv1): build them, check
# them, upload them to s3://orakl-open-source-data/drevalpy_h5mu/<generation>/ and print the
# available_datasets.json entries with their sha256 pins.
# Run from the repository root: scripts/publish_datasets_wizard.sh
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES
# ──────────────────────────────────────────────────────────────────────────

BUCKET_PREFIX="s3://orakl-open-source-data/drevalpy_h5mu"
ASSEMBLED="data/07_assembled"
DATASETS=(CCLE CTRPv1 CTRPv2 GDSC1 GDSC2 PDX_Bruna BeatAML2 PRISM_19Q4 PRISM_20Q2 TOYv1)
ENV_FILE="data/cache/publish_datasets_wizard.env"   # resumable answers; /data/cache/ is git-ignored

# aws_cli ARGS... runs the AWS CLI with the profile chosen in stage 1 (if any).
aws_cli() {
  if [[ -n "${AWS_PROFILE_NAME:-}" ]]; then aws --profile "$AWS_PROFILE_NAME" "$@"; else aws "$@"; fi
}

# fail "msg" stops the wizard with an explanation.
fail() { warn "$1"; exit 1; }

run_wizard() {

TOTAL_STAGES=6
mkdir -p "$(dirname "$ENV_FILE")"
[[ -f pyproject.toml && -f dvc.yaml ]] || fail "Run this from the dreval_curation repository root."

banner "Publish all drevalpy datasets (build, check, upload)"

# ── 1. Preflight ──────────────────────────────────────────────────────────
stage "Preflight"
say "Checks the tools, then asks where to publish."
command -v uv  >/dev/null 2>&1 || fail "uv is not on PATH (try: export PATH=\$HOME/.local/bin:\$PATH)"
command -v aws >/dev/null 2>&1 || fail "the AWS CLI is not on PATH (https://docs.aws.amazon.com/cli/latest/userguide/getting-started-install.html)"
if ! uv run --frozen python -c \
  "from drevalpy.components.featurizers.sample.gene_lists import GENE_LISTS_BY_VIEW" >/dev/null 2>&1; then
  warn "The locked drevalpy has no GENE_LISTS_BY_VIEW, so it predates the shipped gene lists."
  step "uv lock --upgrade-package drevalpy && uv sync --frozen, then commit uv.lock"
  exit 1
fi
say "drevalpy with the shipped gene lists is installed. ✓"
say "Datasets: ${DATASETS[*]}"
note "Every generation is a separate folder; publish a new one rather than overwriting an old one,"
note "which released drevalpy versions still read. Check what exists:"
aws_cli s3 ls "$BUCKET_PREFIX/" 2>/dev/null || note "(listing needs credentials; stage 2 signs you in)"
ask GENERATION "Generation folder to publish to (e.g. gen5):"
[[ "$GENERATION" =~ ^gen[0-9]+$ ]] || fail "The generation must look like gen5."
ask AWS_PROFILE_NAME "AWS profile with write access to the bucket (empty = default credentials):"
write_env GENERATION "$GENERATION"
write_env AWS_PROFILE_NAME "$AWS_PROFILE_NAME"
REMOTE_DIR="$BUCKET_PREFIX/$GENERATION"

# ── 2. Credentials ────────────────────────────────────────────────────────
stage "AWS credentials"
say "The upload needs s3:PutObject on $REMOTE_DIR/ with your own credentials."
if ! aws_cli sts get-caller-identity; then
  say "You are not signed in. In another terminal, sign in the way your account does it, e.g.:"
  step "aws sso login${AWS_PROFILE_NAME:+ --profile $AWS_PROFILE_NAME}"
  step "or: aws configure${AWS_PROFILE_NAME:+ --profile $AWS_PROFILE_NAME}"
  pause "Press Enter once signed in"
  aws_cli sts get-caller-identity || fail "Still no valid credentials."
fi
confirm "Is this the account you want to publish with?" || fail "Stopped: switch account and re-run."

# ── 3. Build ──────────────────────────────────────────────────────────────
stage "Build"
say "Brings every assembled file and TOYv1 up to date with DVC."
say "Pending stages:"
uv run --frozen dvc status assemble_mudata assemble_mudata_prism assemble_mudata_rna_only subsample_toy || true
note "Missing files can be fetched with 'uv run --frozen dvc pull <stage>' instead of rebuilt."
note "Rebuilding a fit stage takes hours; the repro below stops rather than fit unless you allow it."
if confirm "Run 'dvc repro' for the assembly stages and subsample_toy now?"; then
  uv run --frozen dvc repro assemble_mudata assemble_mudata_prism assemble_mudata_rna_only subsample_toy
fi
for ds in "${DATASETS[@]}"; do
  [[ -f "$ASSEMBLED/$ds.h5mu" ]] || fail "$ASSEMBLED/$ds.h5mu is missing."
done
uv run --frozen dvc status assemble_mudata assemble_mudata_prism assemble_mudata_rna_only subsample_toy
confirm "Does DVC report everything up to date?" || fail "Stopped: bring the stages up to date first."

# ── 4. Check ──────────────────────────────────────────────────────────────
stage "Check the files"
say "Opens each file (one at a time, backed) and checks its response modality and replicate fits."
for ds in "${DATASETS[@]}"; do
  uv run --frozen python - "$ASSEMBLED/$ds.h5mu" "$ds" <<'PY' || fail "The check of $ds failed, so nothing was uploaded."
import sys

import mudata as md
import pandas as pd

path, name = sys.argv[1], sys.argv[2]
data = md.read_h5mu(path, backed="r")
problems = []
response = data.mod.get("response")
if response is None:
    problems.append("no response modality")
else:
    if any(mod.startswith("response_rr") for mod in data.mod):
        problems.append("still carries random-replicate modalities")
    table = response.uns.get("replicate_fits")
    if not isinstance(table, pd.DataFrame):
        problems.append('response.uns["replicate_fits"] is missing')
    else:
        outside = ~table["sample_id"].astype(str).isin(response.obs_names) | ~table["pubchem_id"].astype(
            str
        ).isin(response.var_names)
        if outside.any():
            problems.append(f"{int(outside.sum())} replicate-fit rows outside the response axes")
        status = table["status"].value_counts().to_dict()
if name == "TOYv1":
    from drevalpy.components.featurizers.sample.gene_lists import GENE_LISTS_BY_VIEW, view_gene_union

    for view, adata in data.mod.items():
        if view in GENE_LISTS_BY_VIEW:
            missing = set(view_gene_union(view)) - set(adata.var_names)
            if missing:
                problems.append(f"{view}: {len(missing)} list genes missing")
    if data.n_obs != 32 or response is None or response.n_vars != 12:
        problems.append(f"expected 32 samples and 12 drugs, got {data.n_obs}")
views = ", ".join(f"{view} {adata.n_obs}x{adata.n_vars}" for view, adata in data.mod.items())
print(f"  {name:11s} {views}")
if response is not None and isinstance(response.uns.get("replicate_fits"), pd.DataFrame):
    print(f"  {'':11s} replicate_fits: {len(table)} rows {status}")
if problems:
    print("  PROBLEMS:", *problems, sep="\n    ")
    sys.exit(1)
PY
done
confirm "Do the shapes and counts above look right?" || fail "Stopped before the upload."

# ── 5. Upload ─────────────────────────────────────────────────────────────
stage "Upload"
say "Target: $REMOTE_DIR/"
aws_cli s3 ls "$REMOTE_DIR/" 2>/dev/null && warn "Files above already exist there and would be overwritten." \
  || say "Nothing exists at the target yet."
for ds in "${DATASETS[@]}"; do
  key="SHA256_$ds"
  printf -v "$key" '%s' "$(sha256sum "$ASSEMBLED/$ds.h5mu" | cut -d' ' -f1)"
  write_env "$key" "${!key}"
  note "$ds.h5mu  $(du -h "$ASSEMBLED/$ds.h5mu" | cut -f1)  ${!key}"
done
confirm "Upload these ${#DATASETS[@]} files to $REMOTE_DIR/?" || fail "Stopped before the upload."
for ds in "${DATASETS[@]}"; do
  aws_cli s3 cp "$ASSEMBLED/$ds.h5mu" "$REMOTE_DIR/$ds.h5mu"
done

# ── 6. Verify the round trip ──────────────────────────────────────────────
stage "Verify the upload"
say "Downloads each object again into a temporary folder and compares checksums."
CHECK_DIR=$(mktemp -d)
for ds in "${DATASETS[@]}"; do
  key="SHA256_$ds"
  aws_cli s3 cp "$REMOTE_DIR/$ds.h5mu" "$CHECK_DIR/$ds.h5mu" --no-progress >/dev/null
  remote_sha=$(sha256sum "$CHECK_DIR/$ds.h5mu" | cut -d' ' -f1)
  rm -f "$CHECK_DIR/$ds.h5mu"
  [[ "$remote_sha" == "${!key}" ]] || fail "Checksum mismatch for $ds: uploaded ${!key}, downloaded $remote_sha."
  say "$ds ✓"
done
rm -rf "$CHECK_DIR"
printf '\n'
say "Paste this into drevalpy's src/drevalpy/data/datasets/available_datasets.json:"
printf '\n    "orakl_%s": { "url": "%s" }\n\n' "$GENERATION" "$REMOTE_DIR"
for ds in "${DATASETS[@]}"; do
  key="SHA256_$ds"
  printf '    "%s": { "source": "orakl_%s", "file": "%s.h5mu", "sha256": "%s" },\n' \
    "$ds" "$GENERATION" "$ds" "${!key}"
done
printf '\n'
note "Then update the docs that quote dataset shapes and run the network-marked tests"
note "against a fresh DREVALPY_CACHE_DIR."
# ──────────────────────────────────────────────────────────────────────────

finish
}

run_wizard "$@"; exit
